example.code:
// Create an integer array with 5 elements (0-4)
var intArray = new ArrayVariant(VariantType.Int32, 5);
intArray[0] = 10;
intArray[1] = 20;

// Create a string array with custom bounds (1-based indexing)
var stringArray = new ArrayVariant(VariantType.String, 1, 5);
stringArray[1] = "First";
stringArray[2] = "Second";

// Resize and change type
intArray.Resize(10, VariantType.String); // Now a 10-element string array

remarks.para:
              Example conversions:


"SGVsbG8=" → byte[] { 0x48, 0x65, 0x6C, 0x6C, 0x6F }

"/9j/4A==" → byte[] { 0xFF, 0xD8, 0xFF, 0xE0 }

"" (empty) → byte[] { } (empty array)

para.code:
// Create from numeric values
BytePercent percent1 = new BytePercent(50);        // 50%
BytePercent percent2 = new BytePercent("75%");     // 75%
BytePercent percent3 = 100;                        // Implicit conversion

// Convert to string
string str = percent1.ToString(CultureInfo.InvariantCulture);                  // "50%"
string hex = percent1.ToHexString();               // "80" (128 in hex)

// Create from hexadecimal
BytePercent percent4 = BytePercent.FromHexString("FF");  // 100%

// Compare values
if (percent1.CompareTo(percent2) < 0)
{
    Console.WriteLine("percent1 is less than percent2");
}

// Serialization
{ "imageData": "iVBORw0KGgoAAAANSUhEUgAAAAUA" }
{ "content": "SGVsbG8gV29ybGQh" }
{ "empty": "" }
{ "nullValue": null }

// Deserialization accepts
"SGVsbG8="      // standard Base64 with padding
"SGVsbG8"       // Base64 without padding (auto-handled)
"SGVs bG8="     // with whitespace (auto-handled)
""              // empty string
null            // null value

