para.code:
// Serialization
{ "binaryData": "DEADBEEF" }
{ "hash": "A1B2C3D4E5F6" }
{ "empty": "" }
{ "nullValue": null }

// Deserialization accepts
"DEADBEEF"  // uppercase
"deadbeef"  // lowercase
"DeAdBeEf"  // mixed case
""          // empty string
null        // null value

// Serialization output
{
  "revisionId": "0000007B",        // 123 decimal
  "documentHash": "DEADBEEF",      // -559038737 decimal
  "colorValue": "FF0000FF",        // ARGB red color
  "negativeOne": "FFFFFFFF",       // -1 decimal
  "zero": "00000000"               // 0 decimal
}

// Deserialization accepts
"0000007B"   // uppercase
"0000007b"   // lowercase
"7B"         // without leading zeros (parsed correctly)
"FFFFFFFF"   // maximum/negative values

// Serialization output
{
  "revisionId": "0000007B",        // 123 decimal
  "documentHash": "DEADBEEF",      // -559038737 decimal
  "colorValue": "FF0000FF",        // ARGB red color
  "zero": "00000000"               // 0 decimal
}

// Deserialization accepts
"0000007B"   // uppercase
"0000007b"   // lowercase
"7B"         // without leading zeros (parsed correctly)
"FFFFFFFFFFFFFFFF"   // maximum values

