remarks.code:
// Simple types
{
  "type": "Int32",
  "value": 42
}

// String type
{
  "type": "String",
  "value": "Hello"
}

// Enum type with valueType
{
  "type": "Enum",
  "valueType": "System.DayOfWeek, System.Private.CoreLib",
  "value": "Monday"
}

// Binary data (Base64-encoded)
{
  "type": "Blob",
  "value": "SGVsbG8sIFdvcmxkIQ=="
}

example.code:
// Create clipboard data for text format
var textData = new VClipboardData
{
    Format = 1, // CF_TEXT
    Data = Encoding.UTF8.GetBytes("Hello, World!"),
    Size = 13
};

// Create clipboard data for bitmap format
var bitmapData = new VClipboardData
{
    Format = 2, // CF_BITMAP
    Data = bitmapBytes,
    Size = (uint)bitmapBytes.Length
};

// Create an integer vector
var intVector = new VectorVariant(VariantType.Int32);
intVector.Add(10);
intVector.Add(20);
intVector.Add(30);

// Create a string vector
var stringVector = new VectorVariant(VariantType.String);
stringVector.Add("First");
stringVector.Add("Second");
stringVector.Insert(1, "Middle");

// Access elements
Console.WriteLine(stringVector[0]); // "First"
Console.WriteLine(stringVector[1]); // "Middle"

remarks.para:
Note that the base type is not strictly enforced by the VectorVariant class itself;
elements of different types can be added. ValueType enforcement depends on the usage context
and serialization implementation.

member.returns:
 if the element was successfully removed from the vector;
otherwise, . This method also returns 
if the element was not found in the vector.

remarks.code:
// Object format with optional baseType
{
  "baseType": "Int32",
  "items": [10, 20, 30]
}

// Simple array format (no baseType)
[10, 20, 30]

// With baseType specified
{
  "baseType": "Int32",
  "items": [10, 20, 30]
}

// Without baseType (simple array)
[10, 20, 30]

example.code:
// Create stream data with version identifier
var versionGuid = new Guid("12345678-1234-1234-1234-123456789ABC");
var binaryData = File.ReadAllBytes("embedded.ole");
var streamData = new VStreamData(versionGuid, binaryData);

// Create empty stream data
var emptyStream = new VStreamData(Guid.Empty, Array.Empty<byte>());

// Access properties
Console.WriteLine($"IVersion: {streamData.IVersion}");
Console.WriteLine($"Size: {streamData.Data.Length} bytes");

